INSERT INTO `web_ads` VALUES (2,'钉钉扫码部署',NULL,'',2,'#',1,'https://www.xbongbong.com/Uploads/image/20200731/aac04375eee8790bb4500a36180b7227.png','','',NULL,NULL,'/Uploads/file/20200731/31dd2c994bce2630b6447a900d824ee9.apk',NULL,'_self'),(3,'扫码下载APP','','',2,'#',2,'https://www.xbongbong.com/Uploads/image/20200810/cb971f88877e4d6f344481de1458e105.png','','','',NULL,'https://cdn3.xbongbong.com/xbbapp/index.html',NULL,'_self'),(5,'移动CRM',NULL,'精细化客户管理与销售过程管理，提升客户转化率与复购率',3,'/chanpin/#wz_57',1,'https://www.xbongbong.com/Uploads/image/20200814/1f20d7b3cb56adde56a9c68a056c69a9.png',NULL,NULL,NULL,NULL,NULL,NULL,'_self'),(6,'进销存','','智能推荐采购与生产计划，精准库存预测，提高交付效率，降低运营成本',3,'/chanpin/#wz_58',2,'https://www.xbongbong.com/Uploads/image/20200814/802f90f258be5d671fd46b329ea72785.png','','','',NULL,'',NULL,'_self'),(7,'资金管理','','统一资金账户管理，预收预付，应收应付，收付款与发票管理为一体，资金管控更轻松',3,'/chanpin/#wz_59',3,'https://www.xbongbong.com/Uploads/image/20200814/002ec2eca3b3f02c52d52b1ef197c741.png','','','',NULL,'',NULL,'_self'),(8,'工单管理','','智能化自动化工单流转，提高服务效率与客户满意度',3,'/chanpin/#wz_60',4,'https://www.xbongbong.com/Uploads/image/20200814/602d5f2a9d3f11480e110008f5031dd0.png','','','',NULL,'',NULL,'_self'),(9,'零代码开发平台','PaaS','无需代码开发，灵活设计在线表单与智能工作流，快速定制应用，满足个性化需求',4,'#',1,'https://www.xbongbong.com/Uploads/image/20200813/cca902cd641cd0082e7d81243ab7b508.png',NULL,NULL,NULL,NULL,NULL,NULL,'_self'),(10,'智能数据分析平台','BI','多维度交叉计算、分析，灵活查询，高效洞察业务数据，助企业快速决策',4,'#',2,'https://www.xbongbong.com/Uploads/image/20200813/c6f2a3d714e44ebf68a9a454c938744b.png','','','',NULL,'',NULL,'_self'),(11,'开放平台','API','连接企业内外部IT系统，让业务和数据畅通无阻',4,'#',3,'https://www.xbongbong.com/Uploads/image/20200813/b854d79401827838ff46b2fab4b9b5c2.png','','','',NULL,'',NULL,'_self'),(12,'拜访量','+72%','',5,'#',1,'https://www.xbongbong.com/Uploads/image/20200805/7c3a68e48acb70626d85dfdd72d29455.png',NULL,NULL,NULL,NULL,NULL,NULL,'_self'),(13,'转化率','+32%','',5,'#',2,'https://www.xbongbong.com/Uploads/image/20200807/874ccfe998c08a913a88b56a51f11614.png','','','',NULL,'',NULL,'_self'),(14,'毛利率','+10%','',5,'#',3,'https://www.xbongbong.com/Uploads/image/20200807/9484378f259f876f06e124e8f3ab5974.png','','','',NULL,'',NULL,'_self'),(15,'销售额','+50%','',5,'#',4,'https://www.xbongbong.com/Uploads/image/20200807/9cc0e028f0af13db8627e74cd16ce880.png','','','',NULL,'',NULL,'_self'),(16,'南京白肯堂商贸有限公司','商贸行业','',6,'#',10,'https://www.xbongbong.com/Uploads/image/20200805/c2de087cc67f1d4ffe0ee3603216fd41.jpg','https://www.xbongbong.com/Uploads/image/20200805/8de70dc7e1f52ed2c8f426eb684fd079.png',NULL,NULL,NULL,NULL,NULL,'_self'),(17,'南京白肯堂商贸有限公司','商贸行业','',6,'#',10,'https://www.xbongbong.com/Uploads/image/20200805/c2de087cc67f1d4ffe0ee3603216fd41.jpg','https://www.xbongbong.com/Uploads/image/20200805/8de70dc7e1f52ed2c8f426eb684fd079.png','','',NULL,'',NULL,'_self'),(18,'南京白肯堂商贸有限公司','商贸行业','',6,'#',10,'https://www.xbongbong.com/Uploads/image/20200805/c2de087cc67f1d4ffe0ee3603216fd41.jpg','https://www.xbongbong.com/Uploads/image/20200805/8de70dc7e1f52ed2c8f426eb684fd079.png','','',NULL,'',NULL,'_self'),(19,'南京白肯堂商贸有限公司','商贸行业','',6,'#',10,'https://www.xbongbong.com/Uploads/image/20200805/c2de087cc67f1d4ffe0ee3603216fd41.jpg','https://www.xbongbong.com/Uploads/image/20200805/8de70dc7e1f52ed2c8f426eb684fd079.png','','',NULL,'',NULL,'_self'),(53,'1',NULL,'',7,'#',7,'https://www.xbongbong.com/Uploads/image/20200810/1bc8a32d3723489a8b69bb5c9357b68a.jpg',NULL,NULL,NULL,NULL,NULL,NULL,'_self'),(54,'2',NULL,'',7,'#',6,'https://www.xbongbong.com/Uploads/image/20200810/8b7c3217b05af5ef2815162613a3c804.jpg',NULL,NULL,NULL,NULL,NULL,NULL,'_self'),(55,'3',NULL,'',7,'#',16,'https://www.xbongbong.com/Uploads/image/20200810/8af48bc10d6074aea6db8d9c05070f92.jpg',NULL,NULL,NULL,NULL,NULL,NULL,'_self'),(56,'4',NULL,'',7,'#',1,'https://www.xbongbong.com/Uploads/image/20200810/815e53065f1c81b74b1600bf8695ea91.jpg',NULL,NULL,NULL,NULL,NULL,NULL,'_self'),(57,'5',NULL,'',7,'#',2,'https://www.xbongbong.com/Uploads/image/20200810/edc0cf874c26e6f3e1d616eba7