INSERT INTO `web_article` VALUES (1,'销帮帮CRM完成4000万A轮融资，金沙江创投独家投资！','','',NULL,NULL,11,'1','https://www.xbongbong.com/Uploads/image/20200817/2ab7b74fc7d9767abf23b5bcab30fde8.png','','','',NULL,NULL,NULL,NULL,2,'',NULL,2485,10,'','','销帮帮CRM创立于2015年，致力于为企业提供专业、易用和安全的数字化销售管理平台，帮助企业建立以客户为中心的创新业务增长模式，让企业获得更大成功。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL),(4,'渠道经理—华中大区','','11-18K','武汉',NULL,9,'','','',NULL,NULL,NULL,NULL,NULL,NULL,2,'',NULL,1,12,'','','',NULL,NULL,'<p><strong>岗位职责</strong>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL),(5,'全面支持','',NULL,NULL,NULL,14,'','https://www.xbongbong.com/Uploads/image/20200807/b9561eaa3f80f2eec27adbea5c0d8204.png','','',NULL,NULL,NULL,NULL,NULL,2,'',NULL,5,5,'','','专业技术团队维护支持、7*12小时客服支持，相互协同成单',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','','',1,0,1596178267,1596178267,1598497554,10,NULL),(6,'专业培训','',NULL,NULL,NULL,14,'','https://www.xbongbong.com/Uploads/image/20200807/1b2a012dbd791606609dde2d1ccefd7e.png','','',NULL,NULL,NULL,NULL,NULL,2,'',NULL,NULL,4,'','','定期组织交流、培训、远程指导等，为伙伴增加创收机会',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','','',1,0,1596178286,1596178286,1598497541,10,NULL),(7,'收获丰厚','',NULL,NULL,NULL,14,'','https://www.xbongbong.com/Uploads/image/20200807/cd90ed9be620ff51a739adae271ecad0.png','','',NULL,NULL,NULL,NULL,NULL,2,'',NULL,NULL,3,'','','提供高额返点，政策扶持，为伙伴储备人才，拓展市场',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','','',1,0,1596178287,1596178287,1598497496,10,NULL),(8,'资本优势','',NULL,NULL,NULL,14,'','https://www.xbongbong.com/Uploads/image/20200807/d7d32458f3ac967c9e07d8b911851e14.png','','',NULL,NULL,NULL,NULL,NULL,2,'',NULL,1,2,'','','16年获千万天使轮投资，19年获金沙江4000万元A轮融资',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','','',1,0,1596178288,1596178288,1598498211,10,NULL),(9,'良好口碑','',NULL,NULL,NULL,14,'','https://w