CREATE TABLE `web_simgs2` (
  `id` mediumint NOT NULL AUTO_INCREMENT,
  `bid` smallint DEFAULT '0' COMMENT '栏目ID',
  `title` varchar(100) DEFAULT '' COMMENT '名称',
