  `ord` int DEFAULT '10' COMMENT '排序',
  `content` text COMMENT '内容',
  `addtime` int DEFAULT NULL COMMENT '发布时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
